/// <summary>
/// This class copies the batch job and create new batch job for every period
/// </summary>
internal final class METCopyToNewBatchJobsFeature 
{
    DialogField         fieldCalendar;
    DialogField         fieldStartDate;
    DialogField         fieldEndDate;
    DialogField         fieldDescription;
    FiscalCalendarID    calendar;
    FiscalCalendarRecId calendarRecId;
    TransDate           startDate;
    TransDate           endDate;
    BatchCaption        description;
    RecId               refBatchJobRecId;

}

Method.Source:
/// <summary>
/// Dialog construction
/// </summary>
/// <returns>returns the object</returns>
public boolean dialog()
{
    Dialog  dialog = new Dialog("@MET:METCaption");

    fieldCalendar       = dialog.addField(extendedTypeStr(FiscalCalendarRecId), "@MET:METCalendar");
    fieldStartDate      = dialog.addField(extendedTypeStr(TransDate), "@MET:METStartDate");
    fieldEndDate        = dialog.addField(extendedTypeStr(TransDate), "@MET:METEndDate");
    fieldDescription    = dialog.addField(extendedTypeStr(BatchCaption), "@MET:METDescription");

    fieldDescription.fieldControl().helptext("@MET:METBatchHelpText");
    fieldDescription.value(this.getrefBatch().Caption);
    FormBuildReferenceGroupControl fieldCalendarControl = fieldCalendar.control();
    fieldCalendarControl.registerOverrideMethod(methodStr(FormReferenceGroupControl, modified), methodStr(METCopyToNewBatchJobsFeature, calendarModified), this);

    if (dialog.run())
    {
        calendarRecId = fieldCalendar.value();
        startDate     = fieldStartDate.value();
        endDate       = fieldEndDate.value();
        description   = fieldDescription.value();

        return true;
    }
    return false;
}

/// <summary>
/// To set the default values start and end of the period
/// </summary>
/// <param name = "_control">fiscalYear field control</param>
/// <returns>true if value changed otherwise false</returns>
public boolean calendarModified(FormReferenceGroupControl _control)
{
    boolean ret = _control.modified();

    if (ret)
    {
        FiscalCalendarYear  fiscalYear;
        FiscalCalendarRecId selectedCalendar = str2Int64(_control.valueStr());

        if (selectedCalendar)
        {
            select firstonly RecId, StartDate, EndDate from fiscalYear
                where fiscalYear.FiscalCalendar == selectedCalendar
                      && fiscalYear.StartDate   <= today()
                      && fiscalYear.EndDate     >= today();

            if (fiscalYear.RecId)
            {
                fieldStartDate.value(fiscalYear.StartDate);
                fieldEndDate.value(fiscalYear.EndDate);
            }
        }
    }

    return ret;
}

/// <summary>
/// Copying the batch jobs
/// </summary>
public void run()
{
    FiscalCalendarPeriod    period;
    BatchJob                newBatchJob, refBatchJob;
    Batch                   refBatchTask, newBatchTask;

    refBatchJob = this.getrefBatch();

    while select period
        where period.FiscalCalendar == calendarRecId
            && period.StartDate     <= endDate 
            && period.EndDate       >= startDate
            && period.Type          == FiscalPeriodType::Operating
    {
        str newDescription = description;

        if(strFind(newDescription, "%1", 1, strLen(newDescription)))
        {
            newDescription = strReplace(newDescription, "%1", period.periodName());
        }

        if(strFind(newDescription, "%2", 1, strLen(newDescription)))
        {
            newDescription = strReplace(newDescription, "%2", int2Str(year(period.EndDate)));
        }

        BatchJob            existingBatch;
        SysRecurrenceData   recurrenceData;
        container           param;

        select firstonly existingBatch
            where existingBatch.Caption    == newDescription
                  && existingBatch.Company == curExt();

        if (existingBatch.RecId)
        {
            warning(strFmt("@MET:METWarningCaption", newDescription));
            continue;
        }

        try
        {
            ttsbegin;

            newBatchJob.clear();
            newBatchJob.data(refBatchJob);
            newBatchJob.RecId               = 0;
            newBatchJob.Caption             = newDescription;
            newBatchJob.Status              = BatchStatus::Hold;
            newBatchJob.OrigStartDateTime   = DateTimeUtil::newDateTime(period.EndDate, DateTimeUtil::time(refBatchJob.OrigStartDateTime));
            recurrenceData                  = refBatchJob.recurrenceData;
            recurrenceData                  = conPoke(recurrenceData, 6, period.EndDate);
            newBatchJob.recurrenceData      = SysRecurrence::setRecurrenceStartDate(recurrenceData, period.EndDate);

            newBatchJob.insert();

            this.copyAlerts(refBatchJob, newBatchJob);
            Map taskMapping = new Map(Types::Int64, Types::Int64);

            while select refBatchTask 
                where refBatchTask.BatchJobId == refBatchJob.RecId
            {
                this.insertBatchTask(newBatchTask, refBatchTask, refBatchTask.Parameters, newBatchJob, newDescription, period);

                taskMapping.insert(refBatchTask.RecId, newBatchTask.RecId);
            }

            this.copyConstraints(refBatchJob, taskMapping);
            ttscommit;
        }
        catch
        {
            throw error("@MET:METBATCHERROR" + period.Name);
        }
    }
}

/// <summary>
/// This method copies the BatchJob alert messages
/// </summary>
/// <param name = "refBatchJob">original BatchJob buffer</param>
/// <param name = "newBatchJob">new BatchJob buffer</param>
private void copyAlerts(BatchJob refBatchJob, BatchJob newBatchJob)
{
    BatchJobAlerts originalAlert;
    BatchJobAlerts newAlert;
    var insertList = new RecordInsertList(tableNum(BatchJobAlerts), true);

    while select originalAlert
        where originalAlert.BatchJobId == refBatchJob.RecId
    {
        newAlert.data(originalAlert);
        newAlert.BatchJobId = newBatchJob.RecId;

        insertList.add(newAlert);
    }

    insertList.insertDatabase();
}

/// <summary>
/// This method will insert the Batch Task
/// </summary>
/// <param name = "newBatchTask">newBatchTask buffer</param>
/// <param name = "refBatchTask">origianl batchTask buffer</param>
/// <param name = "param">Parameters container</param>
/// <param name = "newBatchJob">new BatchJob buffer</param>
/// <param name = "newDescription">Description of the new BatchJob</param>
/// <param name = "period">modified Parameters container</param>
public void insertBatchTask(Batch newBatchTask, Batch refBatchTask, container param, BatchJob newBatchJob, str newDescription, FiscalCalendarPeriod period)
{
    newBatchTask.clear();
    newBatchTask.data(refBatchTask);
    newBatchTask.RecId      = 0;
    newBatchTask.Caption    = newDescription;
    newBatchTask.Status     = BatchStatus::Hold;
    newBatchTask.BatchJobId = newBatchJob.RecId;

    switch(newBatchTask.className())
    {
        case classStr(TAMRebateCreateTransController):
            param = this.modifyRebateParameters(newBatchTask.Parameters, period);
            break;

        case classStr(TAMRebatePostController):
            param = this.modifyPostParameters(newBatchTask.Parameters, period);
            break;

        case classstr(METVendorRebateOffRemittanceCalcController):
            param = this.modifyVendorParameters(newBatchTask.Parameters, period);
            break;

        case classStr(METTAMRebateCreateTransController_Provision), classStr(METTAMRebateCreateTransController_Rebate), classStr(METTAMRebateCreateTransController_WriteOff):
            param = this.modifyRebateCreateTransParameters(newBatchTask.Parameters, period);
            break;

        case classStr(METTAMRebatePostController_Provision), classStr(METTAMRebatePostController_Rebate), classStr(METTAMRebatePostController_WriteOff):
            param = this.modifyRebatePostParameters(newBatchTask.Parameters, period);
            break;
        case classStr(METRebateCombinedController):
            param  = this.modifyRebatePostCombinedParameters(newBatchTask.Parameters, period);
            break;

    }

    newBatchTask.Parameters = param;

    newBatchTask.insert();
}

/// <summary>
/// This method copies the constraints of the batchjob
/// </summary>
/// <param name = "originalJob">original batchjob buffer</param>
/// <param name = "taskMapping">contains batch tasks</param>

private void copyConstraints(BatchJob originalJob, Map taskMapping)
{
    var insertList = new RecordInsertList(tableNum(BatchConstraints), true);

    BatchConstraints originalConstraint;
    Batch originalTask;
    while select originalConstraint
        exists join originalTask
            where originalTask.RecId			== originalConstraint.BatchId
                  && originalTask.BatchJobId	== originalJob.RecId
    {
        if (!taskMapping.exists(originalConstraint.BatchId)
            || !taskMapping.exists(originalConstraint.DependsOnBatchId))
        {
            throw error("@ApplicationFoundation:CopyBatchJobFailed");
        }

        RecId newBatchId            = taskMapping.lookup(originalConstraint.BatchId);
        RecId newDependsOnBatchId   = taskMapping.lookup(originalConstraint.DependsOnBatchId);

        BatchConstraints newConstraint;
        newConstraint.data(originalConstraint);
        newConstraint.BatchId           = newBatchId;
        newConstraint.DependsOnBatchId  = newDependsOnBatchId;
        insertList.add(newConstraint);
    }

    insertList.insertDatabase();
}

/// <summary>
/// This method modify the parameters of the TAMRebateCreateTransController extension classes
/// </summary>
/// <param name = "_params">Parameters container</param>
/// <param name = "_period">Current Period of the Financial calendar</param>
/// <returns>return the Parameter container</returns>
private container modifyRebateCreateTransParameters(container _params, FiscalCalendarPeriod _period)
{
    container level1, level2, level3, level4, level5, level6, level7;

    level1  = conPeek(_params, 4);
    level2  = conPeek(level1, 8);
    level3  = conPeek(level2, 1);
    level4  = conPeek(level3, 2);
    level5  = conPeek(level4, 2);
    level6  = conPeek(level5, 1);
    level6  = conPoke(level6, 2, _period.StartDate);
    level7  = conPeek(level5, 9);
    level7  = conPoke(level7, 2, _period.EndDate);

    level5  = conPoke(level5, 1, level6);
    level5  = conPoke(level5, 9, level7);
    level4  = conPoke(level4, 2, level5);
    level3  = conPoke(level3, 2, level4);
    level2  = conPoke(level2, 1, level3);
    level1  = conPoke(level1, 8, level2);
    _params = conPoke(_params, 4, level1);

    return _params;
}

/// <summary>
/// This method modify the parameters of the TAMRebatePostController extension classes
/// </summary>
/// <param name = "_params">Parameters container</param>
/// <param name = "_period">Current Period of the Financial calendar</param>
/// <returns>return the Parameter container</returns>
private container modifyRebatePostParameters(container _params, FiscalCalendarPeriod _period)
{
    container level1, level2, level3, level4, level5, level6, level7, level8;

    level1  = conPeek(_params, 4);
    level2  = conPeek(level1, 8);
    level3  = conPeek(level2, 1);
    level4  = conPeek(level3, 2);
    level5  = conPeek(level4, 2);
    level6  = conPeek(level5, 1);
    level6  = conPoke(level6, 2, _period.StartDate);
    level7  = conPeek(level5, 10);
    level7  = conPoke(level7, 2, _period.EndDate);
    level8  = conPeek(level5, 11);
    level8  = conPoke(level8, 2, _period.EndDate);

    level5  = conPoke(level5, 1, level6);
    level5  = conPoke(level5, 10, level7);
    level5  = conPoke(level5, 11, level8);

    level4  = conPoke(level4, 2, level5);
    level3  = conPoke(level3, 2, level4);
    level2  = conPoke(level2, 1, level3);
    level1  = conPoke(level1, 8, level2);
    _params = conPoke(_params, 4, level1);

    return _params;
}

/// <summary>
/// This method modify the parameters of the METRebateCombinedController extension classes
/// </summary>
/// <param name = "_params">Parameters container</param>
/// <param name = "_period">Current Period of the Financial calendar</param>
/// <returns>return the Parameter container</returns>
private container modifyRebatePostCombinedParameters(container _params, FiscalCalendarPeriod _period)
{
    container level1, level2, level3, level4, level5, level6, level7, level8;

    level1  = conPeek(_params, 4);
    level2  = conPeek(level1, 8);
    level3  = conPeek(level2, 2);
    level4  = conPeek(level3, 2);
    level5  = conPeek(level4, 2);
    level6  = conPeek(level5, 2);
    level6  = conPoke(level6, 2, _period.StartDate);
    level7  = conPeek(level5, 11);
    level7  = conPoke(level7, 2, _period.EndDate);
    level8  = conPeek(level5, 12);
    level8  = conPoke(level8, 2, _period.EndDate);

    level5  = conPoke(level5, 2, level6);
    level5  = conPoke(level5, 11, level7);
    level5  = conPoke(level5, 12, level8);

    level4  = conPoke(level4, 2, level5);
    level3  = conPoke(level3, 2, level4);
    level2  = conPoke(level2, 2, level3);
    level1  = conPoke(level1, 8, level2);
    _params = conPoke(_params, 4, level1);

    return _params;
}

