/// <summary>
/// This method modify the parameters of the METVendorRebateOffRemittanceCalcController class
/// </summary>
/// <param name = "_params">Parameters container</param>
/// <param name = "_period">Current Period of the Financial calendar</param>
/// <returns>return the Parameter container</returns>
public container modifyVendorParameters(container _params, FiscalCalendarPeriod _period)
{
    container level1, level2, level3, level4, level5, level6, level7;

    level1  = conPeek(_params, 4);
    level2  = conPeek(level1, 8);
    level3  = conPeek(level2, 1);
    level4  = conPeek(level3, 2);
    level5  = conPeek(level4, 2);

    level6  = conPeek(level5, 1);
    level6  = conPoke(level6, 2, _period.StartDate);
    level7  = conPeek(level5, 8);
    level7  = conPoke(level7, 2, _period.EndDate);

    level5  = conPoke(level5, 1, level6);
    level5  = conPoke(level5, 8, level7);
    level4  = conPoke(level4, 2, level5);
    level3  = conPoke(level3, 2, level4);
    level2  = conPoke(level2, 1, level3);
    level1  = conPoke(level1, 8, level2);
    _params = conPoke(_params, 4, level1);

    return _params;
}

/// <summary>
/// Creating instance of the class
/// </summary>
/// <returns>instance of the current class</returns>
public static METCopyToNewBatchJobsFeature construct()
{
    return new METCopyToNewBatchJobsFeature();
}

/// <summary>
/// Entry point of the batch job
/// </summary>
/// <param name = "_args">The Args buffer</param>
public static void main(Args _args)
{
    METCopyToNewBatchJobsFeature controller = METCopyToNewBatchJobsFeature::construct();

    if (!_args && _args.dataset() != tableNum(BatchJob))
    {
        throw error("@MET:METBATCHERROR");
    }

    BatchJob record = _args.record();
    controller.initFromBatchJob(record.RecId);

    if (controller.dialog())
    {
        controller.run();
    }
}

/// <summary>
/// Storing the reference batch job recId
/// </summary>
/// <param name = "_recId">Recid of the current batch job  record</param>
public void initFromBatchJob(RecId _recId)
{
    refBatchJobRecId = _recId;
}

/// <summary>
/// Find the BatchJob buffer
/// </summary>
/// <returns>Batch job current record</returns>
protected BatchJob getrefBatch()
{
    BatchJob refBatchJob;

    select firstonly refBatchJob
        where refBatchJob.RecId == refBatchJobRecId;

    return refBatchJob;
}
